  1	#!/usr/bin/env node
  2	// Convert task declarations from the retired module form (`tasks/<name>/task.mjs`,
  3	// a default-exported object literal) to the data form (`task.json`, pointing at
  4	// the task schema through `$schema`), deleting the module once its JSON exists.
  5	//
  6	// Two callers. The `task-declarations-json` migration record runs this against a
  7	// member's OWN local packs on its nightly update, through the registry's io
  8	// capabilities, so a member converts without anyone remembering to; and the CLI
  9	// below converts a checkout by hand — the canon's own packs, or a member that
 10	// wants it done sooner:
 11	//
 12	//   node engine/migrations/task-declarations-to-json.mjs [--root <repo>] [<task dir>…]
 13	//
 14	// The module's comments cannot survive in the JSON, so they move to the task's
 15	// `README.md`, under one heading, verbatim — mostly they restated the assignment
 16	// beside them, but what was rationale is then still where a reader of the task
 17	// looks, and the update's apply stage reads it to write the task's `description`.
 18	// The conversion prints each block too. A field that is not data (the retired
 19	// `precondition()` function) is dropped, and named in the report line: the
 20	// contract rejects it either way.
 21	//
 22	// Beside the conversion, the second rewrite of the same files: the retired
 23	// `frequency` field (tasks-dispatch DESIGN §5, #1725) folded into `preconditions`
 24	// as the cadence term it always meant. Patched as ANCHORED TEXT, never re-serialized —
 25	// a member's task.json is its author's, and a round-trip would rewrite its layout
 26	// while nothing failed. The `task-cadence-terms` record runs it nightly; the CLI
 27	// runs it after the conversion.
 28	
 29	import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
 30	import { dirname, join, relative, posix } from 'node:path';
 31	import { pathToFileURL } from 'node:url';
 32	
 33	export const TASK_JSON = 'task.json';
 34	export const TASK_MJS = 'task.mjs';
 35	
 36	// The schema every converted file points at, in the two-root form: a member reads
 37	// it out of its mount, the canon out of its own tree.
 38	export const SCHEMA_FILE = 'packs/claudinite-tasks/task.schema.json';
 39	export const schemaPath = (exists) => (exists(`.claudinite/shared/${SCHEMA_FILE}`) ? `.claudinite/shared/${SCHEMA_FILE}` : SCHEMA_FILE);
 40	
 41	// The pack roots a checkout's tasks live under. A member's own are the local
 42	// packs; the canon also carries the shared packs at the repo root.
 43	export const LOCAL_PACK_ROOT = '.claudinite/local/packs';
 44	export const CANON_PACK_ROOT = 'packs';
 45	
 46	// The order a declaration's keys are written in, grouped by what they say: what
 47	// the task is, when it runs, what it may write, then the two phases — code work,
 48	// then the agent. A key not listed keeps its place after the listed ones.
 49	export const KEY_ORDER = [
 50	  '$schema', 'id', 'description',
 51	  'schedule_after', 'trigger', 'preconditions',
 52	  'expected_outcome', 'automerge', 'on_interrupt', 'invocation_endpoint',
 53	  'code_work', 'code_work_timeout', 'code_work_required_secrets',
 54	  'agent_model', 'model_from_request', 'agent_instructions', 'agent_execution_timeout',
 55	];
 56	export function orderTaskKeys(decl) {
 57	  const rank = (k) => { const i = KEY_ORDER.indexOf(k); return i === -1 ? KEY_ORDER.length : i; };
 58	  return Object.fromEntries(Object.entries(decl).sort(([a], [b]) => rank(a) - rank(b)));
 59	}
 60	
 61	// The JSON text for a declaration object, keys in KEY_ORDER. Returns the keys
 62	// that could not be carried (functions, undefined) so the caller can say so.
 63	export function serializeTaskDeclaration(decl, schemaRelative) {
 64	  const dropped = Object.keys(decl).filter((k) => typeof decl[k] === 'function' || decl[k] === undefined);
 65	  // An empty expression is spelled by absence: a task requiring nothing states no
 66	  // conditions. Whether anything asks it is `trigger`, which is written either way.
 67	  const data = Object.fromEntries(Object.entries(decl)
 68	    .filter(([k, v]) => !dropped.includes(k) && !(k === 'preconditions' && Array.isArray(v) && v.length === 0)));
 69	  return { text: `${JSON.stringify(orderTaskKeys({ $schema: schemaRelative, ...data }), null, 2)}\n`, dropped };
 70	}
 71	
 72	// The comment lines a module carried, for the report: everything outside the
 73	// object literal, so a header explaining why the task exists is not lost silently.
 74	export function moduleComments(source) {
 75	  const out = [];
 76	  for (const line of source.split('\n')) {
 77	    const whole = /^\s*(\/\/|\/\*|\*\/|\*)\s?(.*)$/.exec(line);
 78	    if (whole) { out.push(whole[2]); continue; }
 79	    // A trailing `// …` on a field line — the value's own note. A `//` inside a
 80	    // string value (a URL) is not one; the field's quote closes before the marker.
 81	    const trailing = /^[^'"]*(?:'[^']*'|"[^"]*")?[^'"]*?\s\/\/\s?(.*)$/.exec(line);
 82	    if (trailing) out.push(trailing[1]);
 83	  }
 84	  return out.join('\n').trim();
 85	}
 86	
 87	// Every `<root>/<pack>/tasks/<task>/` directory under the given pack roots that
 88	// carries a task.mjs, repo-relative and posix. `listDir(p)` returns the entry
 89	// names of a directory, or null when it is not one.
 90	export function taskDirsWithModule(packRoots, { listDir, exists }) {
 91	  const out = [];
 92	  for (const root of packRoots) {
 93	    for (const pack of listDir(root) ?? []) {
 94	      const tasks = `${root}/${pack}/tasks`;
 95	      for (const task of listDir(tasks) ?? []) {
 96	        const dir = `${tasks}/${task}`;
 97	        if (exists(`${dir}/${TASK_MJS}`)) out.push(dir);
 98	      }
 99	    }
100	  }
101	  return out.sort();
102	}
103	
104	// The section a task's README gains for its module's comments.
105	export const NOTES_HEADING = '## Why the declaration reads as it does';
106	export function readmeWithNotes(existing, id, comments) {
107	  const section = `\n${NOTES_HEADING}\n\nCarried over from the declaration's comments when it became ${TASK_JSON}.\n\n${comments}\n`;
108	  return `${existing ? `${existing.replace(/\n*$/, '\n')}` : `# ${id}\n`}${section}`;
109	}
110	
111	// The conversion deletes the module, so any sibling that imported it would stop
112	// resolving — and a task whose worker cannot load parks its lane rather than
113	// running degraded. Rewrite the import in place, preserving the quote style, and
114	// carry the JSON import attribute the runtime requires.
115	export const rewriteTaskImport = (text) => text.replace(
116	  /(\bfrom\s*)(['"])\.\/task\.mjs\2/g,
117	  (_m, from, q) => `${from}${q}./task.json${q} with { type: ${q}json${q} }`,
118	);
119	
120	// Every sibling .mjs in the task folder, except the module being converted.
121	export function rewriteTaskImporters(dir, io) {
122	  const rewritten = [];
123	  for (const name of io.listDir(dir) ?? []) {
124	    if (!name.endsWith('.mjs') || name === TASK_MJS) continue;
125	    const at = `${dir}/${name}`;
126	    const before = io.read(at);
127	    if (before == null) continue;
128	    const after = rewriteTaskImport(before);
129	    if (after !== before) { io.write(at, after); rewritten.push(name); }
130	  }
131	  return rewritten;
132	}
133	
134	// Convert the task.mjs in each directory. Capabilities, all repo-relative:
135	//   exists(p), read(p), write(p, text), remove(p), importModule(p) -> module
136	// Returns one report line per directory. A directory already carrying a
137	// task.json keeps it and only loses the module — the JSON is the declaration,
138	// and a second conversion must not clobber an edit made since the first.
139	export async function convertTaskDeclarations(taskDirs, io) {
140	  const schema = schemaPath(io.exists);
141	  const applied = [];
142	  for (const dir of taskDirs) {
143	    const mjs = `${dir}/${TASK_MJS}`;
144	    const json = `${dir}/${TASK_JSON}`;
145	    if (!io.exists(mjs)) continue;
146	    if (io.exists(json)) {
147	      io.remove(mjs);
148	      const also = rewriteTaskImporters(dir, io);
149	      applied.push(`${mjs}: deleted — ${json} already exists and is the declaration`
150	        + (also.length ? ` (rewrote the import in ${also.join(', ')})` : ''));
151	      continue;
152	    }
153	    const decl = (await io.importModule(mjs)).default;
154	    if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
155	      applied.push(`${mjs}: not converted — its default export is not a declaration object`);
156	      continue;
157	    }
158	    const comments = moduleComments(io.read(mjs) ?? '');
159	    const { text, dropped } = serializeTaskDeclaration(decl, posix.relative(dir, schema));
160	    io.write(json, text);
161	    io.remove(mjs);
162	    const rewritten = rewriteTaskImporters(dir, io);
163	    if (comments) {
164	      const readme = `${dir}/README.md`;
165	      io.write(readme, readmeWithNotes(io.read(readme), decl.id ?? dir.slice(dir.lastIndexOf('/') + 1), comments));
166	    }
167	    applied.push(`${mjs} -> ${json}${dropped.length ? ` (dropped non-data field${dropped.length > 1 ? 's' : ''}: ${dropped.join(', ')})` : ''}`
168	      + (rewritten.length ? ` (rewrote the import in ${rewritten.join(', ')})` : '')
169	      + (comments ? `\n  comments not carried over:\n${comments.split('\n').map((l) => `    ${l}`).join('\n')}` : ''));
170	  }
171	  return applied;
172	}
173	
174	// The io over a real checkout — the same capability names the migration
175	// registry's callers build, so the record and the CLI run one converter.
176	export function checkoutIo(root) {
177	  const abs = (p) => join(root, p);
178	  return {
179	    exists: (p) => existsSync(abs(p)),
180	    read: (p) => (existsSync(abs(p)) ? readFileSync(abs(p), 'utf8') : null),
181	    write: (p, text) => { mkdirSync(dirname(abs(p)), { recursive: true }); writeFileSync(abs(p), text); },
182	    remove: (p) => rmSync(abs(p), { force: true }),
183	    listDir: (p) => { try { return readdirSync(abs(p)); } catch { return null; } },
184	    importModule: (p) => import(pathToFileURL(abs(p)).href),
185	  };
186	}
187	
188	// --- the retired `frequency` field --------------------------------------------
189	
190	// What the field always meant, as the condition that now says it — or null for
191	// `manual`, which meant no schedule and adds no term. The one mapping the
192	// contract's door reads (`cadenceTermFor` in packs/claudinite-tasks/calendar.mjs),
193	// spelled again here because the engine imports no pack; the engine test pins the
194	// two to each other over every accepted value.
195	const cadenceTermFor = (frequency) => (frequency === 'manual' ? null : `due:${frequency}`);
196	
197	// The field wherever it sits: on a line of its own (the converter's layout, and
198	// nearly every hand-written one) or inline in a one-line object. The commas
199	// around it are captured so the patch keeps exactly the separators the file needs.
200	const FREQUENCY_FIELD = /(,[ \t]*)?"frequency"[ \t]*:[ \t]*"([^"]*)"([ \t]*,)?/;

