209	// null where there is no field or where the patch would leave the file unparsable
210	// (the file is then left alone; the contract reports it as it is).
211	export function retireFrequencyText(source) {
212	  const text = String(source ?? '');
213	  const field = FREQUENCY_FIELD.exec(text);
214	  if (!field) return null;
215	  const frequency = field[2];
216	  const term = cadenceTermFor(frequency);
217	  const array = PRECONDITIONS_ARRAY.exec(text);
218	
219	  let out;
220	  if (array) {
221	    let stated;
222	    try { stated = JSON.parse(`[${array[1]}]`); } catch { return null; }
223	    if (!stated.every((e) => typeof e === 'string')) return null;
224	    const kept = stated.filter((e) => e.trim() !== 'none');
225	    const terms = term === null || kept.includes(term) ? kept : [term, ...kept];
226	    if (terms.length === 0) {
227	      // `manual` with nothing beside it: no schedule, which a declaration says by
228	      // stating no "preconditions" at all — both fields go.
229	      out = withoutField(withoutField(text, PRECONDITIONS_FIELD), FREQUENCY_FIELD);
230	      try { JSON.parse(out); } catch { return null; }
231	      return { text: out, term, frequency };
232	    }
233	    const multiline = array[1].includes('\n');
234	    const itemIndent = multiline ? (/\n([ \t]*)"/.exec(array[1])?.[1] ?? '    ') : null;
235	    const closeIndent = multiline ? (/\n([ \t]*)$/.exec(array[1])?.[1] ?? '  ') : null;
236	    const rendered = multiline
237	      ? `"preconditions": [\n${terms.map((t) => `${itemIndent}${JSON.stringify(t)}`).join(',\n')}\n${closeIndent}]`
238	      : `"preconditions": [${terms.map((t) => JSON.stringify(t)).join(', ')}]`;
239	    out = text.replace(PRECONDITIONS_ARRAY, rendered);
240	    out = withoutField(out, FREQUENCY_FIELD);
241	  } else if (term === null) {
242	    // `manual` and no list: the field alone goes, and the declaration states nothing.
243	    out = withoutField(text, FREQUENCY_FIELD);
244	  } else {
245	    // The field's own place becomes the list, its separators kept: a one-entry
246	    // list on its own lines where the field had a line, inline where it was inline.
247	    const [whole, leading = '', , trailing = ''] = field;
248	    const lineStart = text.lastIndexOf('\n', field.index) + 1;
249	    const indent = /^[ \t]*/.exec(text.slice(lineStart))[0];
250	    const ownLine = text.slice(lineStart, field.index).trim() === '' && /^[ \t]*(\n|$)/.test(text.slice(field.index + whole.length));
251	    const list = ownLine
252	      ? `"preconditions": [\n${indent}  ${JSON.stringify(term)}\n${indent}]`
253	      : `"preconditions": [${JSON.stringify(term)}]`;
254	    out = text.slice(0, field.index) + leading + list + trailing + text.slice(field.index + whole.length);
255	  }
256	  try { JSON.parse(out); } catch { return null; }
257	  return { text: out, term, frequency };
258	}
259	
260	// Remove a field (matched with its separators, groups 1 and 3) from the text. A
261	// field alone on its line takes the line with it — and, where it was the object's
262	// last key, the comma the key before it carried; an inline field leaves exactly one
263	// separator behind.
264	function withoutField(text, re) {
265	  const f = re.exec(text);
266	  const [whole, leading, , trailing] = f;
267	  const start = f.index;
268	  const end = start + whole.length;
269	  const lineStart = text.lastIndexOf('\n', start) + 1;
270	  const lineEndAt = text.indexOf('\n', end);
271	  const lineEnd = lineEndAt === -1 ? text.length : lineEndAt;
272	  const restOfLine = text.slice(lineStart, start) + text.slice(end, lineEnd);
273	  if (restOfLine.trim() === '') {
274	    let before = text.slice(0, lineStart);
275	    if (!trailing) before = before.replace(/,[ \t]*\n$/, '\n');
276	    return before + text.slice(lineEnd + 1);
277	  }
278	  const separator = leading && trailing ? ',' : '';
279	  const rest = text.slice(end);
280	  // A key follows: its spacing is the removed field's to give back. None follows
281	  // (the object's last inline key): the closing brace keeps the space it had.
282	  return text.slice(0, start) + separator + (trailing ? rest.replace(/^[ \t]+(?=\S)/, leading ? ' ' : '') : rest);
283	}
284	
285	// Every `<root>/<pack>/tasks/<task>/` directory under the given pack roots that
286	// carries a task.json, repo-relative and posix.
287	export function taskDirsWithJson(packRoots, { listDir, exists }) {
288	  const out = [];
289	  for (const root of packRoots) {
290	    for (const pack of listDir(root) ?? []) {
291	      const tasks = `${root}/${pack}/tasks`;
292	      for (const task of listDir(tasks) ?? []) {
293	        const dir = `${tasks}/${task}`;
294	        if (exists(`${dir}/${TASK_JSON}`)) out.push(dir);
295	      }
296	    }
297	  }
298	  return out.sort();
299	}
300	
301	// --- the unstated `trigger` -----------------------------------------------------
302	
303	// Whether a declaration states any condition — the pack's `statesConditions`
304	// (packs/claudinite-tasks/calendar.mjs), spelled again here because the engine
305	// imports no pack; the engine test pins the two over one vector set. An entry
306	// carrying only separators states nothing, which is why this is not a length test.
307	const statesConditions = (preconditions) => (Array.isArray(preconditions) ? preconditions : [])
308	  .some((e) => String(e ?? '').split('||').some((alt) => alt.trim() !== ''));
309	
310	const TRIGGER_FIELD = /(^|[{,\s])"trigger"[ \t]*:/;
311	// The field goes immediately BEFORE one of these, never after a key: the last key
312	// of an object carries no comma, so appending past one is what breaks the file.
313	// `preconditions` first, the pair being one sentence; `expected_outcome` is the
314	// fallback because the contract requires it, so a declaration always carries one.
315	const TRIGGER_ANCHORS = [/"preconditions"[ \t]*:/, /"expected_outcome"[ \t]*:/];
316	
317	// Patch one task.json's text to state the trigger its shape already implied.
318	// Returns `{ text, trigger }`, or null where the field is already there, the file
319	// does not parse, no anchor was found, or the patch would leave it unparsable.
320	// Run AFTER the frequency fold, so the conditions it reads are the final ones.
321	export function stateTriggerText(source) {
322	  const text = String(source ?? '');
323	  if (TRIGGER_FIELD.test(text)) return null;
324	  let decl;
325	  try { decl = JSON.parse(text); } catch { return null; }
326	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return null;
327	  const trigger = statesConditions(decl.preconditions) ? 'schedule' : 'request';
328	  const field = `"trigger": ${JSON.stringify(trigger)}`;
329	
330	  for (const anchor of TRIGGER_ANCHORS) {
331	    const m = anchor.exec(text);
332	    if (!m) continue;
333	    // A key on its own line gets a line of its own at the same indent; one inline
334	    // in a one-line object gets exactly the separator that object uses.
335	    const lineStart = text.lastIndexOf('\n', m.index) + 1;
336	    const indent = text.slice(lineStart, m.index);
337	    const out = indent.trim() === ''
338	      ? `${text.slice(0, m.index)}${field},\n${indent}${text.slice(m.index)}`
339	      : `${text.slice(0, m.index)}${field}, ${text.slice(m.index)}`;
340	    try { JSON.parse(out); } catch { return null; }
341	    return { text: out, trigger };
342	  }
343	  return null;
344	}
345	
346	// Bring the task.json in each directory up to the current scheduling vocabulary:
347	// the retired `frequency` folded into `preconditions`, and the `trigger` its shape
348	// implied stated outright. One report line per file changed; a file a patch cannot
349	// be made to is reported and left.
350	export async function updateTaskSchedulingFields(taskDirs, io) {
351	  const applied = [];
352	  for (const dir of taskDirs) {
353	    const json = `${dir}/${TASK_JSON}`;
354	    let source = io.read(json);
355	    if (source === null) continue;
356	    if (FREQUENCY_FIELD.test(source)) {
357	      const patched = retireFrequencyText(source);
358	      if (!patched) {
359	        applied.push(`${json}: not rewritten — its "frequency" could not be folded into "preconditions" as text; edit it by hand`);
360	        continue;
361	      }
362	      source = patched.text;
363	      io.write(json, source);
364	      applied.push(patched.term === null
365	        ? `${json}: frequency "${patched.frequency}" dropped — no schedule, so no preconditions`
366	        : `${json}: frequency "${patched.frequency}" → "${patched.term}", first in preconditions`);
367	    }
368	    const stated = stateTriggerText(source);
369	    if (stated) {
370	      io.write(json, stated.text);
371	      applied.push(`${json}: trigger "${stated.trigger}" stated — the answer its conditions already gave`);
372	    }
373	  }
374	  return applied;
375	}
376	
377	export async function main(argv = process.argv.slice(2)) {
378	  let root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
379	  const dirs = [];
380	  for (let i = 0; i < argv.length; i++) {
381	    if (argv[i] === '--root') root = argv[++i];
382	    else dirs.push(argv[i]);
383	  }
384	  const io = checkoutIo(root);
385	  const named = dirs.map((d) => posix.normalize(relative(root, join(root, d)).split('\\').join('/')));
386	  const targets = dirs.length ? named : taskDirsWithModule([CANON_PACK_ROOT, LOCAL_PACK_ROOT], io);
387	  const applied = await convertTaskDeclarations(targets, io);
388	  console.log(applied.length ? applied.join('\n') : 'no task.mjs to convert');
389	  const retired = await updateTaskSchedulingFields(dirs.length ? named : taskDirsWithJson([CANON_PACK_ROOT, LOCAL_PACK_ROOT], io), io);
390	  console.log(retired.length ? retired.join('\n') : 'no task.json carries a frequency');
391	}
392	
393	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
394	  main().catch((e) => { console.error(`task-declarations-to-json failed: ${e.message}`); process.exit(1); });
395	}

