   328	test('task-cadence-terms record: applies only where the mounted pack reads BOTH fields, in either root', async () => {
   329	  const m = (await loadMigrations()).find((x) => x.id === 'task-cadence-terms');
   330	  assert.ok(m, 'discovered');
   331	  assert.equal(m.updateTaskSchedulingFields, true);
   332	  // The two files the probe reads, each answering for one of the two rewrites.
   333	  const capable = (p) => (p.endsWith('.json') ? '{ "properties": { "trigger": {} } }
' : 'export const cadenceTermFor = (frequency) => …;
');
   334	  const inRoot = (root) => async (p) => (p.startsWith('.claudinite/shared/') === root ? capable(p) : null);
   335	  assert.equal(await m.appliesTo(inRoot(true)), true, 'a member's mount');
   336	  assert.equal(await m.appliesTo(inRoot(false)), true, 'the canon's own tree');
   337	  assert.equal(await m.appliesTo(async () => 'export const FREQUENCIES = [];
'), false, 'an older pack');
   338	  // Each half alone is not enough: writing either field into a mount that does not
   339	  // read it is what the probe exists to stop.
   340	  assert.equal(await m.appliesTo(async (p) => (p.endsWith('.json') ? null : capable(p))), false, 'the cadence term without the schema');
   341	  assert.equal(await m.appliesTo(async (p) => (p.endsWith('.json') ? capable(p) : null)), false, 'the schema without the cadence term');
   342	  assert.equal(await m.appliesTo(async () => null), false, 'an unreadable mount is not capable');
   343	  assert.equal(await m.legacyPresent(() => true, async () => 'x'), false);
   344	  assert.equal(m.applyStage, undefined, 'a text rewrite needs no session');
   345	});

